  // 管(消化管)。太い線の上に地の色の線を重ねて、2本線の管に見せる
  function gut(d, w) {
    return '<path class="fig-shape" style="stroke-width:' + w + 'px;stroke-linecap:butt" d="' + d + '"/>' +
      '<path class="fig-halo" fill="none" style="stroke-width:' + (w - 3.5) + 'px;stroke-linecap:butt" d="' + d + '"/>';
  }

  // B9 ヒトの消化器官(正面から見た図)。opts は JHS.labels と同じ。
  // 記号は、A 食道、B 肝臓、C 胃、D 胆のう、E すい臓、F 小腸、G 大腸、H 肛門
  function figDigestive(opts) {
    opts = opts || {};
    var asKey = !!(opts.keys || opts.mark), s = "";
    s += gut("M172 8V62", 9);                                                                                    // 食道
    s += '<path class="fig-shape fig-fill-2" d="M82 62C100 50 142 50 160 62C158 76 136 86 100 90C86 88 78 76 82 62Z"/>';   // 肝臓
    // 小腸(胃の出口から、折れ曲がって大腸の始まりへ)
    s += gut("M148 105C134 110 131 130 137 148C140 157 146 160 152 160H186C194 160 194 172 186 172H140C132 172 132 184 140 184H186C194 184 194 196 186 196H122", 8);
    s += '<path class="fig-shape fig-fill-0" d="M168 60C188 56 210 68 210 88C210 108 190 118 172 114C162 112 154 108 148 110L146 100C154 98 160 94 162 84C163 74 164 66 168 60Z"/>';   // 胃
    s += '<path class="fig-detail" d="M120 102C126 112 130 116 134 120"/>';                                       // 胆汁の通り道
    s += '<ellipse class="fig-shape fig-fill" cx="118" cy="96" rx="6" ry="9" transform="rotate(-20 118 96)"/>';   // 胆のう
    s += '<path class="fig-shape fig-fill-2" d="M150 124C170 118 198 120 212 126C198 134 170 136 150 132Z"/>';     // すい臓
    s += gut("M118 208V146H206V204C206 220 184 222 164 222V234", 13);                                            // 大腸
    s += '<path class="fig-shape" d="M111.5 208H124.5"/>';                                                        // 大腸の始まり(行き止まり)
    s += JHS.labels([
      { key: "A", name: "食道", from: [172, 28], to: [236, 24] },
      { key: "B", name: "肝臓", from: [96, 70], to: [66, 52], side: "left" },
      { key: "C", name: "胃", from: [196, 84], to: [236, 76] },
      { key: "D", name: "胆のう", from: [116, 96], to: [66, 100], side: "left" },
      { key: "E", name: "すい臓", from: [202, 127], to: [236, 124] },
      { key: "F", name: "小腸", from: [176, 178], to: [236, 176] },
      { key: "G", name: "大腸", from: [118, 170], to: [66, 164], side: "left" },
      { key: "H", name: "肛門", from: [164, 232], to: [124, 228], side: "left" }
    ], opts);
    return JHS.svg(320, 240, asKey ? "ヒトの消化にかかわる器官を、正面から見た図。部分に記号がついている"
      : "ヒトの消化器官。食物は、口から食道、胃、小腸、大腸を通って肛門へ進む。肝臓、胆のう、すい臓は、食物が通らない", s);
  }

  // B10 柔毛のつくり。opts.keys: true で、A(毛細血管)と B(リンパ管)の記号にする(問題用)
  function figVillus(opts) {
    opts = opts || {};
    var s = "";
    s += '<path class="fig-shape" d="M24 172H66M154 172H196"/>';
    s += '<path class="fig-shape fig-fill-0" d="M66 172V72C66 20 154 20 154 72V172"/>';
    s += '<path class="fig-detail fig-fill-2" d="M104 172V76C104 64 116 64 116 76V172"/>';                         // リンパ管
    s += '<path class="fig-line" d="M86 172V72C86 52 100 44 110 44C120 44 134 52 134 72V172M86 136C92 132 94 124 86 118M134 128C128 124 126 114 134 108M86 90C94 86 96 78 90 64"/>';   // 毛細血管
    var parts = [
      { key: "A", name: "毛細血管", from: [134, 96], to: [204, 92] },
      { key: "B", name: "リンパ管", from: [112, 140], to: [204, 140] }
    ];
    if (!opts.keys) parts.unshift({ key: "C", name: "柔毛", from: [150, 52], to: [204, 44] });
    s += JHS.labels(parts, opts);
    s += txt(110, 191, "小腸の壁", { cls: "fig-small", anchor: "middle" });
    return JHS.svg(320, 200, opts.keys ? "小腸の壁にある柔毛の断面の図。中を通る2種類の管に記号がついている"
      : "柔毛のつくり。表面のすぐ内側に毛細血管があり、中央にリンパ管が通っている", s);
  }

