  // 神経を伝わる信号の計算に使う数値の組(距離[cm]、速さ[m/s]、時間[1000分の1秒])。時間が割り切れる組だけ
  var NERVE_SETS = [];
  [60, 80, 90, 100, 120, 150, 160, 180].forEach(function (d) {
    [40, 50, 60, 80, 100].forEach(function (v) {
      if ((d * 10) % v === 0) NERVE_SETS.push({ d: d, v: v, ms: d * 10 / v });
    });
  });

