  // =====================================================================
  // 2-9 化学変化と質量
  // =====================================================================
  // 質量は10倍した整数(0.1g を 1)で計算する。g10 は、その値を「1.2 g」の形にする。
  // 0.01g の位までで表せない値(割り切れない誤答)は null を返し、JHS.choices4 が読みとばす
  function g10(v) {
    if (typeof v !== "number" || !isFinite(v) || v <= 0) return null;
    var h = Math.round(v * 10);
    if (Math.abs(v * 10 - h) > 1e-9) return null;
    return q(h % 10 === 0 ? num(h / 100, 1) : num(h / 100), "g");
  }
  function n10(v) { var h = Math.round(v * 10); return h % 10 === 0 ? num(h / 100, 1) : num(h / 100); }
  function ratioText(key) {
    var M = METAL[key];
    return M.name + "と酸素は、" + M.m + ":" + M.o + " の質量の比で結びつきます。";
  }

