      "気体が発生する反応でも、密閉した容器の中で行えば、全体の質量は変わりません。ふたをあけると、気体が出ていった分だけ質量が小さくなります。金属を空気中で加熱すると質量が大きくなるのは、空気中の酸素が結びつくからです。",
