      "電流の流れにくさを<b>電気抵抗(抵抗)</b>といい、単位は<b>オーム(Ω)</b>です。" + volt(1) + " の電圧を加えたときに " + amp(1) + " の電流が流れる抵抗が " + ohm(1) + " です。",
      "電圧を V[V]、電流を I[A]、抵抗を R[Ω] とすると、" + rule("V = R × I") + " です。電流を求めるときは I = V ÷ R、抵抗を求めるときは R = V ÷ I と変形します。電流が mA で示されているときは、" + rule("A になおしてから") + "計算します。",
      "電圧を横軸、電流を縦軸にとったグラフは、原点を通る直線になります。同じ電圧で比べて、" + rule("電流が小さい(傾きが小さい)ほうが、抵抗が大きい") + "です。",
      "2つの抵抗器を<b>直列</b>につなぐと、全体の抵抗は " + rule("R = R₁ + R₂") + " になります。<b>並列</b>につなぐと、電流の通り道がふえるので、全体の抵抗は" + rule("どちらの抵抗よりも小さく") + "なります(" + JHS.frac("1", "R") + " = " + JHS.frac("1", "R₁") + " + " + JHS.frac("1", "R₂") + ")。",
      "金属のように電流が流れやすい物質を<b>導体</b>、ガラスやゴムのように電流がほとんど流れない物質を<b>不導体(絶縁体)</b>、その中間の性質をもつ物質を<b>半導体</b>といいます。"
